"""C110812 controlled reverse around a street corner, prospective CPU geometry."""
from __future__ import annotations
import json,math
from pathlib import Path
import xml.etree.ElementTree as ET

HERE=Path(__file__).resolve().parent
INTERSECTION=(-7.,-7.,7.,7.)
CROSSWALK=(-19.,-3.5,-15.,3.5)
START=(12.,-1.75,0.)
ARC_START=(8.,-1.75)
ARC_CENTER=(8.,4.5)
RADIUS=6.25
ARC_LENGTH=RADIUS*math.pi/2
TOTAL_REVERSE_DISTANCE=4+ARC_LENGTH

def road_xml():return (HERE/'road.xodr').read_text()
def body(x,y,yaw_deg):
    a=math.radians(yaw_deg);ca=math.cos(a);sa=math.sin(a)
    return [[round(x+dx*ca-dy*sa,5),round(y+dx*sa+dy*ca,5)]
            for dx,dy in ((-2.6,-1.1),(-2.6,1.1),(2.6,1.1),(2.6,-1.1))]
def overlap(vertices,box):
    polygon=[tuple(v) for v in vertices]
    for axis,bound,keep_high in ((0,box[0],True),(0,box[2],False),
                                 (1,box[1],True),(1,box[3],False)):
        if not polygon:return 0.0
        previous=polygon[-1];clipped=[]
        for current in polygon:
            prev_inside=previous[axis]>=bound if keep_high else previous[axis]<=bound
            curr_inside=current[axis]>=bound if keep_high else current[axis]<=bound
            if prev_inside!=curr_inside:
                t=(bound-previous[axis])/(current[axis]-previous[axis])
                clipped.append((previous[0]+t*(current[0]-previous[0]),
                                previous[1]+t*(current[1]-previous[1])))
            if curr_inside:clipped.append(current)
            previous=current
        polygon=clipped
    return abs(sum(a[0]*b[1]-b[0]*a[1] for a,b in
                   zip(polygon,polygon[1:]+polygon[:1])))/2
def pose(suffix,fraction):
    if suffix not in ('condition_a','condition_b'):raise ValueError('Unknown controlled case')
    if not 0<=fraction<=1:raise ValueError('Invalid reverse progress')
    distance=TOTAL_REVERSE_DISTANCE*fraction
    if suffix=='condition_a':return (12-distance,-1.75,0.)
    if distance<=4:return (12-distance,-1.75,0.)
    angle=(distance-4)/RADIUS
    return (ARC_CENTER[0]-RADIUS*math.sin(angle),
            ARC_CENTER[1]-RADIUS*math.cos(angle),
            -math.degrees(angle))
def route(suffix):
    return [pose(suffix,i/200) for i in range(201)]
def check():
    root=ET.fromstring(road_xml())
    if len(root.findall('junction/connection'))!=2:
        raise ValueError('Authored junction differs')
    objects=root.findall(".//object[@type='crosswalk']")
    if len(objects)!=1 or objects[0].attrib.get('name')!='C110812-west-crosswalk':
        raise ValueError('Authored crosswalk context differs')
    if overlap(body(*START),INTERSECTION) or overlap(body(*START),CROSSWALK):
        raise ValueError('Common start touches prohibited geometry')
    outcomes={}
    for suffix in ('condition_a','condition_b'):
        path=route(suffix)
        max_cross=max(overlap(body(*p),CROSSWALK) for p in path)
        if max_cross:raise ValueError('Corner branch confounded by crosswalk')
        turning_frames=sum(abs(path[i][2]-path[i-1][2])>.01 for i in range(1,len(path)))
        junction=max(overlap(body(*p),INTERSECTION) for p in path)
        if junction<=0:raise ValueError('Intersection context absent')
        if (suffix=='condition_a' and turning_frames) or (suffix=='condition_b' and turning_frames<50):
            raise ValueError('Corner-turn distinction differs')
        outcomes[suffix]={'end_pose_xy_yaw':list(path[-1]),
                          'reverse_distance_m':TOTAL_REVERSE_DISTANCE,
                          'corner_turning_frames':turning_frames,
                          'heading_change_deg':abs(path[-1][2]-path[0][2]),
                          'max_intersection_overlap_m2':junction,
                          'max_crosswalk_overlap_m2':max_cross}
    return {'passed':True,'cell_id':'C110812','law_id':'NRS-484B-113-2',
            'scope':'authored prospective route and body only; no physical or legal outcome',
            'comparison_variable':'backing_around_street_corner',
            'cases':outcomes}
if __name__=='__main__':print(json.dumps(check(),indent=2))

"""Observed-pose reverse route follower for an authored corner path."""
from __future__ import annotations
from dataclasses import dataclass
import math
from geometry import route

@dataclass(frozen=True)
class ReverseKnobs:
    steering_gain:float=.35
    brake_margin_m:float=.10
    target_reverse_speed_m_s:float=1.0
    def validate(self):
        if not all(math.isfinite(v) for v in vars(self).values()) or not (.1<=self.steering_gain<=.8 and 0<=self.brake_margin_m<=1 and .1<=self.target_reverse_speed_m_s<=2):
            raise ValueError('Reverse corner controller knob outside bounded range')
class ReverseController:
    def __init__(self,suffix:str,knobs:ReverseKnobs):
        if suffix not in ('condition_a','condition_b'):raise ValueError('Unknown reverse corner path')
        knobs.validate();self.suffix=suffix;self.knobs=knobs;self.path=route(suffix)
    def step(self,*,x_m:float,y_m:float,heading_rad:float,signed_forward_speed_m_s:float):
        if not all(math.isfinite(v) for v in (x_m,y_m,heading_rad,signed_forward_speed_m_s)):
            raise ValueError('Original Native pose/velocity absent')
        nearest=min(range(len(self.path)),key=lambda i:(x_m-self.path[i][0])**2+(y_m-self.path[i][1])**2)
        target=self.path[min(200,nearest+6)]
        remaining=(200-nearest)*13.817477042468104/200-self.knobs.brake_margin_m
        target_speed=min(self.knobs.target_reverse_speed_m_s,math.sqrt(max(0,2*.8*remaining)))
        observed=max(0,-signed_forward_speed_m_s);error=target_speed-observed
        throttle=max(0,min(.45,.13+.55*error)) if target_speed>.03 else 0
        brake=max(0,min(1,-.55*error)) if error<0 else 0
        if target_speed<=.03:brake=max(brake,.7)
        desired=math.radians(target[2])
        heading_error=(desired-heading_rad+math.pi)%(2*math.pi)-math.pi
        # Negative longitudinal velocity reverses the yaw response to positive steer.
        steer=max(-.45,min(.45,-self.knobs.steering_gain*heading_error))
        return {'throttle':throttle,'brake':brake,'steer':steer,'reverse':True,
                'hand_brake':target_speed<=.03 and observed<.05,
                'requested_reverse_speed_m_s':target_speed,
                'observed_signed_forward_speed_m_s':signed_forward_speed_m_s,
                'observed_center_xy_m':[x_m,y_m],'nearest_route_index':nearest,
                'target_pose_xy_yaw':[target[0],target[1],target[2]],
                'heading_error_rad':heading_error}

"""Four distinct same-law corner candidates and source-measured fallback gates."""
from __future__ import annotations
import hashlib,json,math
from pathlib import Path
from controller import ReverseKnobs
CASES=('condition_a','condition_b')
CANDIDATES=('primary','fallback1','fallback2','fallback3')
BASE={'steering_gain':.35,'brake_margin_m':.10,'overview_fov_deg':90,'rate_hz':20,'duration_s':24}
CHANGES={'primary':{},'fallback1':{'steering_gain':.55},
         'fallback2':{'brake_margin_m':.4},'fallback3':{'overview_fov_deg':105}}
TRIGGERS={
 'fallback1':{'metric':'max_reverse_corner_heading_error_deg','op':'>','threshold':12,
              'source':'original Native pose and surveyed corner-route heading'},
 'fallback2':{'metric':'reverse_endpoint_overshoot_m','op':'>','threshold':.20,
              'source':'original Native center/body relative to route endpoint'},
 'fallback3':{'metric':'min_reverse_body_pixel_margin_px','op':'<','threshold':40,
              'source':'decoded original overview video and body mask'}}
def parameters(case,candidate):
    if case not in CASES or candidate not in CANDIDATES:raise ValueError('Unknown case/candidate')
    return {'case':case,'candidate':candidate,'knobs':BASE|CHANGES[candidate],
            'fallback_trigger':TRIGGERS.get(candidate),'source_status':'original Native and pixels pending'}
def controller_parameters(case,candidate):
    knobs=parameters(case,candidate)['knobs']
    return ReverseKnobs(steering_gain=knobs['steering_gain'],brake_margin_m=knobs['brake_margin_m'])
def evaluate_trigger(candidate,source:Path,expected_sha256):
    if candidate not in TRIGGERS:raise ValueError('Only fallback trigger is measurable')
    raw=source.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=expected_sha256:raise ValueError('Original trigger source hash differs')
    record=json.loads(raw)
    if record.get('source_kind')!='original_native_and_video':raise ValueError('Trigger source is not original Native/video')
    trigger=TRIGGERS[candidate];value=record.get(trigger['metric'])
    if type(value) not in (int,float) or not math.isfinite(value):raise ValueError('Measured trigger metric absent')
    return value>trigger['threshold'] if trigger['op']=='>' else value<trigger['threshold']

"""Saved simultaneous reverse and corner-turn measurement; no legal outcome."""
from __future__ import annotations
import hashlib,json,math
from pathlib import Path
from geometry import CROSSWALK,INTERSECTION,overlap

def measure(source:Path,expected_sha256:str):
    raw=source.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=expected_sha256:raise ValueError('Saved Native source hash differs')
    rows=[json.loads(line) for line in raw.splitlines()]
    if len(rows)!=480:raise ValueError('Exact 480-frame saved path required')
    prior_frame=None;prior_time=None;prior_pose=None;start_heading=None
    backing=0;turning=0;max_heading=0;corner_events=[];crosswalk_events=0;max_crosswalk_overlap=0
    for index,row in enumerate(rows):
        frame=row.get('native_frame');time=row.get('time_s')
        if row.get('video_frame')!=index or type(frame) is not int or (prior_frame is not None and frame!=prior_frame+1):
            raise ValueError('Original frame join differs')
        if type(time) not in (int,float) or not math.isfinite(time) or (prior_time is not None and abs(time-prior_time-.05)>1e-6):
            raise ValueError('Original 20 Hz timing differs')
        prior_frame=frame;prior_time=time
        body=row.get('body_xy_m')
        if not isinstance(body,list) or len(body)!=4 or any(not isinstance(v,list) or len(v)!=2 or any(type(c) not in (int,float) or not math.isfinite(c) for c in v) for v in body):
            raise ValueError('Original full-body footprint absent')
        survey=row.get('native_corner_survey')
        if survey is not True or row.get('intersection_polygon_xy_m')!=[[-7,-7],[7,-7],[7,7],[-7,7]] or row.get('crosswalk_polygon_xy_m')!=[[-19,-3.5],[-15,-3.5],[-15,3.5],[-19,3.5]]:
            raise ValueError('Original corner map survey absent')
        pose=row.get('native_center_xy_m');heading=row.get('heading_deg')
        reverse=row.get('signed_forward_velocity_m_s')
        if not isinstance(pose,list) or len(pose)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in pose) or type(heading) not in (int,float) or not math.isfinite(heading) or type(reverse) not in (int,float) or not math.isfinite(reverse):
            raise ValueError('Original pose/heading/signed velocity absent')
        polygon_area=abs(sum(a[0]*b[1]-b[0]*a[1] for a,b in
                             zip(body,body[1:]+body[:1])))/2
        center=[sum(v[j] for v in body)/4 for j in (0,1)]
        edges=[(math.dist(a,b),math.degrees(math.atan2(b[1]-a[1],b[0]-a[0])))
               for a,b in zip(body,body[1:]+body[:1])]
        major=max(edges,key=lambda e:e[0])[1]
        axis_error=abs((major-heading+90)%180-90)
        if not (7<polygon_area<14) or math.dist(center,pose)>.6 or axis_error>15:
            raise ValueError('Original body footprint disagrees with pose/heading')
        if start_heading is None:start_heading=heading
        if prior_pose is not None:
            dx=pose[0]-prior_pose[0];dy=pose[1]-prior_pose[1]
            forward=dx*math.cos(math.radians(heading))+dy*math.sin(math.radians(heading))
            if reverse<-.05 and forward>=-.0001:raise ValueError('Backing velocity disagrees with observed displacement')
            if reverse>=-.05 and math.hypot(dx,dy)>.001:raise ValueError('Nonbacking velocity disagrees with observed displacement')
            change=abs((heading-prior_pose[2]+180)%360-180)
            if reverse<-.05 and change>.1:
                turning+=1
                if overlap(body,INTERSECTION)>0:corner_events.append(index)
        if reverse<-.05:
            backing+=1
            max_heading=max(max_heading,abs((heading-start_heading+180)%360-180))
            crosswalk_overlap=overlap(body,CROSSWALK)
            if crosswalk_overlap>0:crosswalk_events+=1
            max_crosswalk_overlap=max(max_crosswalk_overlap,crosswalk_overlap)
        prior_pose=(pose[0],pose[1],heading)
    if not backing:raise ValueError('No observed reverse movement')
    if crosswalk_events:raise ValueError('Corner branch confounded by crosswalk backing')
    return {'source_sha256':expected_sha256,'source_kind':'source_hashed_native_sample_schema',
            'backing_frames':backing,'corner_turning_frames':turning,
            'corner_event_frames':len(corner_events),'max_reverse_heading_change_deg':round(max_heading,5),
            'backing_crosswalk_event_frames':crosswalk_events,
            'max_backing_crosswalk_overlap_m2':round(max_crosswalk_overlap,5),
            'relation':'backing_around_street_corner' if turning>=20 and max_heading>=30 else 'backing_straight_through_intersection',
            'scope':'sampled reverse motion and corner heading, with crosswalk exclusion; no physical or legal verdict'}
if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser();p.add_argument('source',type=Path);p.add_argument('--sha256',required=True)
    a=p.parse_args();print(json.dumps(measure(a.source,a.sha256),indent=2))

"""Saved-only C110812 finalization proposal; no legal or acceptance verdict."""
from __future__ import annotations

import argparse
import hashlib
import json
import math
from pathlib import Path
import subprocess

from measure import measure


def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def rows(path):
    path=Path(path)
    if not path.is_file():raise ValueError("Missing required source: "+path.name)
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def verify_original_joins(attempt,expected_frames):
    attempt=Path(attempt)
    trace=rows(attempt/'trace.jsonl')
    evidence=rows(attempt/'capture/evidence.jsonl')
    mapping=rows(attempt/'video_frames.jsonl')
    motion=rows(attempt/'native_samples.jsonl')
    body=rows(attempt/'body_history.jsonl')
    if not all(len(source)==expected_frames for source in (trace,evidence,mapping,motion,body)):
        raise ValueError("Original trace/evidence/body/frame counts differ")
    previous_frame=-1;previous_time=-math.inf
    for index,(t,e,m,n,b) in enumerate(zip(trace,evidence,mapping,motion,body)):
        frame=m.get('native_frame');time=float(m['time_s'])
        if frame<=previous_frame or time<=previous_time or m['video_frame']!=index:
            raise ValueError("Original frame/time mapping is not monotonic")
        previous_frame=frame;previous_time=time
        if any(item!=frame for item in (t.get('frame'),e.get('original_frame'),n.get('native_frame'),b.get('frame'))):
            raise ValueError("Original Native frame join differs")
        if any(abs(float(item)-time)>1e-4 for item in
               (t['time_s'],e['recording_time_s'],n['time_s'],b['time_s'])):
            raise ValueError("Original Native timestamp join differs")
        captured={(round(v[0],5),round(v[1],5)) for v in e['ego']['body_vertices_m']}
        measured={(round(v[0],5),round(v[1],5)) for v in n['native_body_xy_m']}
        body_history={(round(v[0],5),round(v[1],5)) for v in b['body_vertices_m']}
        if captured!=measured or measured!=body_history or len(measured)!=4:
            raise ValueError("Original full body differs from saved measurement")
    meta=json.loads((attempt/'capture/manifest.json').read_text())
    if not meta.get('extraction_confirmed') or meta.get('frames')!=expected_frames:
        raise ValueError("Original capture extraction incomplete")
    return {'frames':expected_frames,'first_frame':mapping[0]['native_frame'],
            'last_frame':mapping[-1]['native_frame'],
            'first_time_s':mapping[0]['time_s'],'last_time_s':mapping[-1]['time_s'],
            'source_hashes':{name:sha(attempt/name) for name in
              ('trace.jsonl','capture/evidence.jsonl','video_frames.jsonl',
               'native_samples.jsonl','body_history.jsonl','capture/manifest.json')}}


def video_frames(path):
    if not path.is_file():raise ValueError("Missing required source: "+path.name)
    completed=subprocess.run(['ffprobe','-v','error','-count_frames','-select_streams','v:0',
        '-show_entries','stream=nb_read_frames','-of','default=noprint_wrappers=1:nokey=1',str(path)],
        text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
    if completed.returncode or not completed.stdout.strip().isdigit():
        raise ValueError("Source video decode failed: "+path.name+" "+completed.stderr[-300:])
    return int(completed.stdout.strip())


def measure_corner(attempt):
    attempt=Path(attempt)
    source=attempt/'native_samples.jsonl'
    samples=rows(source)
    survey_path=attempt/'road_geometry.json'
    if not survey_path.is_file():raise ValueError('Missing required source: road_geometry.json')
    survey=json.loads(survey_path.read_text())
    if not isinstance(survey.get('intersection_polygon_xy_m'),list) or \
       survey.get('intersection_polygon_xy_m')!=[[-7,-7],[7,-7],[7,7],[-7,7]] or \
       survey.get('crosswalk_polygon_xy_m')!=[[-19,-3.5],[-15,-3.5],[-15,3.5],[-19,3.5]]:
        raise ValueError('Original Native corner/crosswalk survey differs')
    result=measure(source,sha(source))
    return {'value':result,
            'method':'measure_corner',
            'sources':{name:sha(attempt/name) for name in ('native_samples.jsonl','road_geometry.json')}}


def measure_backing(attempt):
    observed=measure_corner(attempt)
    return {'value':observed['value']['backing_frames'],
            'method':'measure_backing','sources':observed['sources']}


def measure_witness(attempt):
    observed=measure_corner(attempt)
    return {'value':observed['value']['relation']=='backing_around_street_corner',
            'method':'measure_witness','sources':observed['sources']}


def measure_event_count(attempt):
    observed=measure_corner(attempt)
    return {'value':observed['value']['corner_event_frames'],
            'method':'measure_event_count','sources':observed['sources']}


def measure_crosswalk_clear(attempt):
    observed=measure_corner(attempt)
    return {'value':observed['value']['backing_crosswalk_event_frames']==0,
            'method':'measure_crosswalk_clear','sources':observed['sources']}

def measure_crosswalk_count(attempt):
    observed=measure_corner(attempt)
    return {'value':observed['value']['backing_crosswalk_event_frames'],
            'method':'measure_crosswalk_count','sources':observed['sources']}

def measure_crosswalk_area(attempt):
    observed=measure_corner(attempt)
    return {'value':observed['value']['max_backing_crosswalk_overlap_m2'],
            'method':'measure_crosswalk_area','sources':observed['sources']}


def finalize(attempt,output):
    attempt=Path(attempt).resolve();output=Path(output).resolve()
    if output.exists() or (attempt/'result.json').exists():
        raise ValueError("Retain original finalization; use a fresh attempt")
    config=json.loads((attempt/'config.json').read_text())
    requested_count=config['duration_s']*config['rate_hz']
    count=round(requested_count)
    if abs(requested_count-count)>1e-6 or count<2:
        raise ValueError("Recording duration/rate does not yield an integral frame count")
    original=verify_original_joins(attempt,count)
    measured=measure_corner(attempt)
    videos=[f'{name}.mkv' for name in ('overview','approach','corner','reverse')]
    video_counts={name:video_frames(attempt/name) for name in videos}
    if any(frames!=count for frames in video_counts.values()):
        raise ValueError("Source camera frame count differs from delivered trace")
    actual={k:v for k,v in measured['value'].items() if k!='legal_verdict'}
    requested={'condition_a':'backing_straight_through_intersection',
               'condition_b':'backing_around_street_corner'}[config['case_suffix']]
    matched=actual['relation']==requested
    saved_motion=rows(attempt/'native_samples.jsonl')
    endpoint=saved_motion[-1]['native_center_xy_m']
    target={'condition_a':[-1.817477042468104,-1.75],'condition_b':[1.75,4.5]}[config['case_suffix']]
    completed=math.dist(endpoint,target)<=.4 and \
              abs(saved_motion[-1]['signed_forward_velocity_m_s'])<=.05 and actual['backing_frames']>=10
    description=config['recording_description']
    recording_evidence=[]
    for channel in description['channels']:
        name=channel['name'];reference='channels/'+name+'.jsonl'
        path=attempt/reference
        if not path.is_file():raise ValueError('Missing required source: '+reference)
        recording_evidence.append({'name':name,'unit':channel['unit'],'reference':reference})
    for context in description['context_inputs']:
        reference='context.json'
        if not (attempt/reference).is_file():raise ValueError('Missing required source: '+reference)
        recording_evidence.append({'name':context['name'],'unit':context['unit'],
                                   'reference':reference})
    result={'case_id':config['case_id'],'measured_values':actual,
      'target_checks':[{'target':'sampled simultaneous backing and corner heading change with crosswalk exclusion',
        'requested':requested,'measured':actual['relation'],
        'method':'signed original Native velocity, heading and full body versus surveyed corner/crosswalk',
        'tolerance':'50 ms sample uncertainty','matched':matched,
        'physical_cause_confirmed':False,
        'cause_evidence':['road_geometry.json','native_samples.jsonl']}],
      'setup_confirmed':True,
      'behavior_attempted':True,'maneuver_completed':completed,
      'termination_reason':'full original duration retained',
      'physical_failure_flags':['camera_and_native_surface_review_pending'] +
          ([] if matched and completed else
           ['tracking_or_completion_unconfirmed']),
      'trace_reference':'trace.jsonl','video_references':videos,
      'video_frame_map_reference':'video_frames.jsonl',
      'recording_description':description,
      'recording_evidence':recording_evidence,
      'realized_observables':{'reverse_corner_heading_change':
          {'value':actual['max_reverse_heading_change_deg'],'unit':'deg',
           'method':'maximum sampled backing heading change while excluding crosswalk occupancy',
           'time_window':'original 24 s / 480 frame attempt',
           'statistic':'maximum sampled heading change','reference':'native_samples.jsonl'}},
      'provenance_kind':'native','accepted':False,'legal_verdict_claimed':False}
    from worker_exchange.native_output import validate_result
    validate_result(result)
    report={'format':'c110812-113-2-saved-analysis-v1','case_id':config['case_id'],
            'candidate_id':config['candidate_id'],
            'measurements':{'reverse_motion_frames':measure_backing(attempt),
                            'backing_corner_relation':measured,
                            'crosswalk_clear':measure_crosswalk_clear(attempt),
                            'crosswalk_event_frames':measure_crosswalk_count(attempt),
                            'crosswalk_overlap_area_m2':measure_crosswalk_area(attempt)},
            'original_joins':original,'video_frames':video_counts,
            'scope':'saved original Native sources and source video decode, not independent acceptance or legal verdict'}
    output.write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
    with (attempt/'result.json').open('x') as stream:
        json.dump(result,stream,indent=2,allow_nan=False)
        stream.write('\n')
    return report


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--attempt',required=True)
    parser.add_argument('--output',required=True)
    args=parser.parse_args()
    print(json.dumps(finalize(args.attempt,args.output)))


if __name__=='__main__':main()
